 "content": "def transform(grid):
    """Extend the solid rectangle's rows and columns to the grid edges.

    A singleton of another color blocks extension only in its row/column and
    direction (on the corresponding ray from the rectangle).
    """
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value:
                counts[value] = counts.get(value, 0) + 1
    main = max(counts, key=counts.get)
    main_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == main]
    r0 = min(r for r, _ in main_cells)
    r1 = max(r for r, _ in main_cells)
    c0 = min(c for _, c in main_cells)
    c1 = max(c for _, c in main_cells)
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and grid[r][c] != main]
    out = [row[:] for row in grid]

    # Extend horizontally from each rectangle row, except toward a marker.
    for r in range(r0, r1 + 1):
        if not any(rr == r and cc < c0 for rr, cc in markers):
            for c in range(c0):
                if out[r][c] == 0:
                    out[r][c] = main
        if not any(rr == r and cc > c1 for rr, cc in markers):
            for c in range(c1 + 1, w):
                if out[r][c] == 0:
                    out[r][c] = main

    # Extend vertically from each rectangle column, except toward a marker.
    for c in range(c0, c1 + 1):
        if not any(cc == c and rr < r0 for rr, cc in markers):
            for r in range(r0):
                if out[r][c] == 0:
                    out[r][c] = main
        if not any(cc == c and rr > r1 for rr, cc in markers):
            for r in range(r1 + 1, h):
                if out[r][c] == 0:
                    out[r][c] = main
    return out
